            <section class="grid gap-5 xl:grid-cols-2"><article class="overflow-x-auto rounded-xl border bg-card"><h3 class="p-4 font-semibold">Ejecución presupuestal</h3><table class="w-full text-sm"><thead class="border-y bg-muted/40 text-left"><tr><th class="px-4 py-3">Categoría</th><th class="px-4 py-3">Habitante</th><th class="px-4 py-3">Presupuesto</th><th class="px-4 py-3">Ejecutado</th><th class="px-4 py-3">Disponible</th></tr></thead><tbody class="divide-y"><tr v-for="line in household.budget.lines" :key="line.id"><td class="px-4 py-3">{{ line.category }}</td><td class="px-4 py-3">{{ line.person || 'Compartido' }}</td><td class="px-4 py-3">{{ money(line.budgeted_amount) }}</td><td class="px-4 py-3">{{ money(line.executed_amount) }}</td><td class="px-4 py-3" :class="line.available_amount < 0 ? 'text-destructive' : ''">{{ money(line.available_amount) }}</td></tr><tr v-if="!household.budget.lines.length"><td colspan="5" class="p-6 text-center text-muted-foreground">Sin presupuesto visible para el mes.</td></tr></tbody></table></article><article class="rounded-xl border bg-card"><h3 class="p-4 font-semibold">Solicitudes por atender</h3><div class="divide-y"><div v-for="item in household.requests" :key="item.id" class="flex justify-between gap-3 p-4 text-sm"><span><strong>{{ item.document }} · {{ item.requester }}</strong><small class="block text-muted-foreground">{{ item.status }} · necesaria {{ item.needed_at }}</small></span><strong>{{ money(item.amount) }}</strong></div><p v-if="!household.requests.length" class="p-6 text-sm text-muted-foreground">Sin solicitudes pendientes.</p></div><Link href="/household" class="m-4 inline-block text-sm text-amber-700 underline">Abrir hogar</Link></article></section>
